<script setup lang="ts">import {ElMessage} from 'element-plus';import {reactive} from 'vue'; import {useRouter} from 'vue-router'; import {useAuth} from '../stores/auth'; const form=reactive({username:'admin',password:'Admin@123456'}), auth=useAuth(),router=useRouter(); async function submit(){try{await auth.login(form.username,form.password);router.push('/')}catch(e:any){ElMessage.error(e.response?.data?.message||'登录失败')}} </script>
<template><div class="login-wrap"><div class="login-card"><h1>TradeFlow CRM</h1><p class="muted">外贸客户、询盘、报价、订单、回款与出运一体化管理</p><el-form label-position="top" @submit.prevent="submit"><el-form-item label="用户名"><el-input v-model="form.username"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password" show-password/></el-form-item><el-button type="primary" native-type="submit" :loading="auth.loading" style="width:100%">登录</el-button></el-form></div></div></template>
